import React, { useState } from "react";
import { ref, uploadBytes, getDownloadURL, deleteObject } from "firebase/storage";
import { doc, updateDoc } from "firebase/firestore";
import { db, storage } from "./firebase";
import { toast } from "react-toastify";
import Form from "react-bootstrap/Form";
import Button from "react-bootstrap/Button";

function GestioneAllegati({ allegati = [], mezzoId, ruolo = "ospite", onAggiorna }) {
  const [file, setFile] = useState(null);
  const [tipo, setTipo] = useState("documento");

  const isAdminOrTecnico = ruolo === "admin" || ruolo === "tecnico";

  const handleFileChange = (e) => {
    const selected = e.target.files[0];
    if (!selected) return;

    if (selected.size > 10 * 1024 * 1024) {
      toast.error("❌ Il file supera i 10MB.");
      return;
    }

    setFile(selected);
  };

  const handleUpload = async () => {
    if (!file || !mezzoId) return;

    const nomeFile = `${Date.now()}_${file.name}`;
    const fileRef = ref(storage, `allegati/${mezzoId}/${nomeFile}`);

    try {
      await uploadBytes(fileRef, file);
      const url = await getDownloadURL(fileRef);

      const nuovoAllegato = {
        url,
        nome: file.name,
        tipo
      };

      const docRef = doc(db, "MEZZI", mezzoId);
      const aggiornati = [...allegati, nuovoAllegato];
      await updateDoc(docRef, { allegati: aggiornati });

      toast.success("📤 Allegato caricato");
      setFile(null);
      if (onAggiorna) onAggiorna();
    } catch (error) {
      console.error("Errore upload:", error);
      toast.error("❌ Errore durante il caricamento");
    }
  };

  const handleDelete = async (a) => {
    if (!isAdminOrTecnico || !a?.url || !mezzoId) return;
    if (!window.confirm(`Vuoi eliminare "${a.nome}"?`)) return;

    try {
      await deleteObject(ref(storage, a.url));
      const docRef = doc(db, "MEZZI", mezzoId);
      const aggiornati = allegati.filter(x => x.url !== a.url);
      await updateDoc(docRef, { allegati: aggiornati });
      toast.success("🗑️ Allegato eliminato");
      if (onAggiorna) onAggiorna();
    } catch (error) {
      console.error("Errore eliminazione:", error);
      toast.error("❌ Errore durante l'eliminazione");
    }
  };

  const raggruppati = {
    foto: allegati.filter(a => a.tipo === "foto"),
    documenti: allegati.filter(a => a.tipo === "documento"),
    certificati: allegati.filter(a => a.tipo === "certificato")
  };

  return (
    <div className="mt-3">
      {isAdminOrTecnico && (
        <Form className="mb-4">
          <Form.Group className="mb-2">
            <Form.Label>📤 Carica nuovo allegato</Form.Label>
            <Form.Control type="file" onChange={handleFileChange} />
          </Form.Group>
          <Form.Select value={tipo} onChange={(e) => setTipo(e.target.value)} className="mb-2">
            <option value="documento">📄 Documento</option>
            <option value="foto">🖼️ Foto</option>
            <option value="certificato">📑 Certificato</option>
          </Form.Select>
          <Button variant="primary" onClick={handleUpload} disabled={!file}>
            Carica
          </Button>
        </Form>
      )}

      {Object.entries(raggruppati).map(([categoria, lista]) => (
        <div key={categoria} className="mb-4">
          <h6 className="text-uppercase text-muted">{categoria}</h6>
          {lista.length === 0 ? (
            <p className="text-muted">Nessun allegato</p>
          ) : (
            lista.map((a, i) => (
              <div key={i} className="d-flex align-items-start gap-3 flex-wrap mb-3">
                {a.tipo === "foto" ? (
                  <a href={a.url} target="_blank" rel="noopener noreferrer" title={a.nome}>
                    <img src={a.url} alt={a.nome} className="img-thumbnail" style={{ maxWidth: "150px" }} />
                  </a>
                ) : a.url.endsWith(".pdf") ? (
                  <iframe src={a.url} title={a.nome} style={{ width: "150px", height: "200px", border: "1px solid #ccc" }} />
                ) : (
                  <a href={a.url} target="_blank" rel="noopener noreferrer" className="btn btn-outline-secondary btn-sm">
                    📄 {a.nome}
                  </a>
                )}
                {isAdminOrTecnico && (
                  <button className="btn btn-sm btn-outline-danger" onClick={() => handleDelete(a)}>
                    🗑️ Elimina
                  </button>
                )}
              </div>
            ))
          )}
        </div>
      ))}
    </div>
  );
}

export default GestioneAllegati;