import React, { useEffect, useState, useCallback } from "react";
import { MapContainer, TileLayer, Marker, Popup, useMap } from "react-leaflet";
import MarkerClusterGroup from "react-leaflet-cluster";
import { collection, getDocs } from "firebase/firestore";
import { db } from "./firebase";
import L from "leaflet";
import "leaflet/dist/leaflet.css";
import "leaflet.heat";
import Form from "react-bootstrap/Form";
import Modal from "react-bootstrap/Modal";
import Button from "react-bootstrap/Button";
import Papa from "papaparse";
import { debounce } from "lodash";

// 🔍 Estrazione provincia e comune da indirizzo
const estraiLocalita = (indirizzo) => {
  if (!indirizzo) return { provincia: "", comune: "" };
  const match = indirizzo.match(/-\s*(\d{5})\s+(.+?)\s+\((\w{2})\)/);
  if (match) {
    return {
      comune: match[2].trim(),
      provincia: match[3].trim()
    };
  }
  return { provincia: "", comune: "" };
};

// 📍 Geolocalizzazione da indirizzo (Nominatim)
const geolocalizzaIndirizzo = async (indirizzo) => {
  const url = `https://nominatim.openstreetmap.org/search?format=json&q=${encodeURIComponent(indirizzo)}`;
  const response = await fetch(url);
  const data = await response.json();
  if (data.length > 0) {
    return {
      lat: parseFloat(data[0].lat),
      lng: parseFloat(data[0].lon)
    };
  }
  return null;
};

// 📤 Esportazione CSV
const esportaClientiCSV = (clienti) => {
  const csv = Papa.unparse(clienti.map(c => ({
    RagioneSociale: c.ragioneSociale,
    Indirizzo: c.indirizzo,
    Comune: c.comune,
    Provincia: c.provincia,
    Email: c.email,
    Telefono: c.telefono
  })));
  const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.setAttribute("download", "clienti_filtrati.csv");
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
};

// 📈 Heatmap Layer
const HeatmapLayer = ({ punti }) => {
  const map = useMap();
  useEffect(() => {
    const heat = L.heatLayer(punti, { radius: 25 }).addTo(map);
    return () => {
      map.removeLayer(heat);
    };
  }, [punti, map]);
  return null;
};

const MappaClienti = () => {
  const [clienti, setClienti] = useState([]);
  const [provincia, setProvincia] = useState("");
  const [comune, setComune] = useState("");
  const [soloUrgenti, setSoloUrgenti] = useState(false);
  const [ricerca, setRicerca] = useState("");
  const [clienteId, setClienteId] = useState("");
  const [dataInizio, setDataInizio] = useState("");
  const [dataFine, setDataFine] = useState("");
  const [tecnico, setTecnico] = useState("");
  const [clienteSelezionato, setClienteSelezionato] = useState(null);
  const [mostraHeatmap, setMostraHeatmap] = useState(false);

  useEffect(() => {
    const fetchClienti = async () => {
      try {
        const snap = await getDocs(collection(db, "CLIENTI"));
        const dati = await Promise.all(
          snap.docs.map(async doc => {
            const raw = doc.data();
            const { provincia, comune } = estraiLocalita(raw.indirizzo);
            let lat = raw.lat;
            let lng = raw.lng;

            if (!lat || !lng) {
              const coords = await geolocalizzaIndirizzo(raw.indirizzo);
              if (coords) {
                lat = coords.lat;
                lng = coords.lng;
              }
            }

            return {
              id: doc.id,
              ...raw,
              provincia,
              comune,
              lat,
              lng,
              interventi: raw.interventi || []
            };
          })
        );
        setClienti(dati.filter(c => c.lat && c.lng));
      } catch (error) {
        console.error("Errore nel caricamento clienti:", error);
      }
    };
    fetchClienti();
  }, []);

  delete L.Icon.Default.prototype._getIconUrl;
  L.Icon.Default.mergeOptions({
    iconRetinaUrl: require("leaflet/dist/images/marker-icon-2x.png"),
    iconUrl: require("leaflet/dist/images/marker-icon.png"),
    shadowUrl: require("leaflet/dist/images/marker-shadow.png"),
  });

  const provinceDisponibili = [...new Set(clienti.map(c => c.provincia).filter(Boolean))].sort();
  const comuniDisponibili = provincia
    ? [...new Set(clienti.filter(c => c.provincia === provincia).map(c => c.comune).filter(Boolean))].sort()
    : [];
  const tecniciUnici = [...new Set(clienti.flatMap(c => c.interventi?.map(i => i.tecnico).filter(Boolean)))];

  const clientiFiltrati = clienti.filter(c => {
    if (clienteId && c.id !== clienteId) return false;
    if (provincia && c.provincia !== provincia) return false;
    if (comune && c.comune !== comune) return false;
    if (soloUrgenti && !c.urgente) return false;
    if (tecnico && !c.interventi?.some(i => i.tecnico === tecnico)) return false;
    if (dataInizio || dataFine) {
      const validi = c.interventi?.filter(i => {
        const d = new Date(i.data.seconds * 1000);
        return (!dataInizio || d >= new Date(dataInizio)) &&
               (!dataFine || d <= new Date(dataFine));
      });
      if (!validi || validi.length === 0) return false;
    }
    if (ricerca && !c.ragioneSociale?.toLowerCase().includes(ricerca.toLowerCase())) return false;
    return true;
  });

  const aggiornaRicerca = useCallback(
    debounce((valore) => setRicerca(valore), 300),
    []
  );

  return (
    <div className="p-4 bg-light rounded">
      <h3 className="mb-4">🗺️ Mappa Clienti</h3>

      <Form className="mb-3 d-flex gap-3 flex-wrap">
        <Form.Group>
          <Form.Label>Provincia</Form.Label>
          <Form.Select value={provincia} onChange={(e) => {
            setProvincia(e.target.value);
            setComune("");
            setClienteId("");
          }}>
            <option value="">Tutte</option>
            {provinceDisponibili.map((p, i) => (
              <option key={i} value={p}>{p}</option>
            ))}
          </Form.Select>
        </Form.Group>

        <Form.Group>
          <Form.Label>Comune</Form.Label>
          <Form.Select value={comune} onChange={(e) => {
            setComune(e.target.value);
            setClienteId("");
          }} disabled={!provincia}>
            <option value="">Tutti</option>
            {comuniDisponibili.map((c, i) => (
              <option key={i} value={c}>{c}</option>
            ))}
          </Form.Select>
        </Form.Group>

        <Form.Group>
          <Form.Label>Cliente</Form.Label>
          <Form.Select value={clienteId} onChange={(e) => setClienteId(e.target.value)}>
            <option value="">Tutti</option>
            {clienti.map(c => (
              <option key={c.id} value={c.id}>
                {c.ragioneSociale}
              </option>
            ))}
          </Form.Select>
        </Form.Group>

        <Form.Group>
          <Form.Label>🔍 Cerca ragione sociale</Form.Label>
          <Form.Control
            type="text"
            placeholder="Es. Officina Rossi"
            onChange={(e) => aggiornaRicerca(e.target.value)}
          />
        </Form.Group>

        <Form.Group>
          <Form.Label>Da</Form.Label>
          <Form.Control type="date" value={dataInizio} onChange={(e) => setDataInizio(e.target.value)} />
        </Form.Group>

        <Form.Group>
          <Form.Label>A</Form.Label>
          <Form.Control type="date" value={dataFine} onChange={(e) => setDataFine(e.target.value)} />
        </Form.Group>

        <Form.Group>
          <Form.Label>Tecnico</Form.Label>
          <Form.Select value={tecnico} onChange={(e) => setTecnico(e.target.value)}>
                        <option value="">Tutti</option>
            {tecniciUnici.map((t, i) => (
              <option key={i} value={t}>{t}</option>
            ))}
          </Form.Select>
        </Form.Group>

        <Form.Group className="d-flex align-items-center gap-2 mt-2">
          <Form.Check
            type="checkbox"
            label="Solo clienti con interventi urgenti"
            checked={soloUrgenti}
            onChange={(e) => setSoloUrgenti(e.target.checked)}
          />
        </Form.Group>

        <Form.Group className="d-flex align-items-center gap-2 mt-2">
          <Form.Check
            type="checkbox"
            label="Visualizza heatmap"
            checked={mostraHeatmap}
            onChange={(e) => setMostraHeatmap(e.target.checked)}
          />
        </Form.Group>

        <Button variant="outline-success" onClick={() => esportaClientiCSV(clientiFiltrati)}>
          📤 Esporta CSV
        </Button>
      </Form>

      <MapContainer center={[43.5, 12.5]} zoom={6} style={{ height: "600px", width: "100%" }}>
        <TileLayer
          attribution='© OpenStreetMap'
          url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
        />
        {mostraHeatmap ? (
          <HeatmapLayer punti={clientiFiltrati.map(c => [c.lat, c.lng, 1])} />
        ) : (
          <MarkerClusterGroup>
            {clientiFiltrati.map((c) => (
              <Marker
                key={c.id}
                position={[c.lat, c.lng]}
                eventHandlers={{ click: () => setClienteSelezionato(c) }}
              >
                <Popup>
                  <strong>{c.ragioneSociale}</strong><br />
                  {c.indirizzo || "Indirizzo non disponibile"}<br />
                  {c.comune}, {c.provincia}<br />
                  {c.urgente ? "⚠️ Interventi urgenti presenti" : "✅ Nessuna urgenza"}
                </Popup>
              </Marker>
            ))}
          </MarkerClusterGroup>
        )}
      </MapContainer>

      <Modal show={!!clienteSelezionato} onHide={() => setClienteSelezionato(null)}>
        <Modal.Header closeButton>
          <Modal.Title>📋 Dettaglio Cliente</Modal.Title>
        </Modal.Header>
        <Modal.Body>
          {clienteSelezionato && (
            <div>
              <p><strong>Ragione Sociale:</strong> {clienteSelezionato.ragioneSociale}</p>
              <p><strong>Indirizzo:</strong> {clienteSelezionato.indirizzo}</p>
              <p><strong>Comune:</strong> {clienteSelezionato.comune}</p>
              <p><strong>Provincia:</strong> {clienteSelezionato.provincia}</p>
              <p><strong>Email:</strong> {clienteSelezionato.email || "—"}</p>
              <p><strong>Telefono:</strong> {clienteSelezionato.telefono || "—"}</p>
              <p><strong>Urgenza:</strong> {clienteSelezionato.urgente ? "⚠️ Sì" : "No"}</p>

              {clienteSelezionato.interventi?.length > 0 ? (
                <div className="mt-3">
                  <h6>🛠️ Interventi associati</h6>
                  <ul>
                    {clienteSelezionato.interventi.map((int, i) => (
                      <li key={i}>
                        {int.tipo} — {new Date(int.data.seconds * 1000).toLocaleDateString("it-IT")} — {int.stato} — {int.tecnico || "Tecnico non assegnato"}
                      </li>
                    ))}
                  </ul>
                </div>
              ) : (
                <p className="text-muted mt-3">Nessun intervento registrato.</p>
              )}
            </div>
          )}
        </Modal.Body>
        <Modal.Footer>
          <Button variant="secondary" onClick={() => setClienteSelezionato(null)}>
            ❌ Chiudi
          </Button>
        </Modal.Footer>
      </Modal>
    </div>
  );
};

export default MappaClienti;