import React from "react";
import Badge from "react-bootstrap/Badge";

/**
 * Visualizza un badge colorato in base allo stato dell'intervento.
 * @param {Object} props
 * @param {string} props.stato
 */
const BadgeStato = ({ stato = "Non definito" }) => {
  const colori = {
    Effettuato: "success",
    Programmato: "warning",
    "In Ritardo": "danger",
    "Non definito": "secondary"
  };

  const variante = colori[stato] || "secondary";

  return <Badge bg={variante}>{stato}</Badge>;
};

export default BadgeStato;